/**
 * Shared API contract types.
 *
 * These mirror the Rust structs in `apps/api/src/domain`. Phase 1 will replace the
 * hand-written section with types generated by `ts-rs` into `./generated` — keep the
 * field names identical to the Rust serialisation so the switch is mechanical.
 */

export type Role = "user" | "super_admin";

export interface SessionUser {
  id: string;
  email: string;
  name: string;
  department: string | null;
  role: Role;
  /** Reserved for category-scoped admins; always null now that only `super_admin` remains. */
  adminScope: { categories?: string[] } | null;
  mustChangePassword: boolean;
}

export interface LoginResponse {
  token: string;
  expiresAt: string;
  user: SessionUser;
  mustChangePassword: boolean;
}

export interface Announcement {
  text: string;
  level: "info" | "warning" | "critical";
  /** ISO-8601 window; absent or null means always visible. */
  activeFrom?: string | null;
  activeTo?: string | null;
}

export interface AppTile {
  id: string;
  name: string;
  url: string;
  description: string | null;
  category: string | null;
  color: string | null;
  sortOrder: number;
  offlineVisible: boolean;
  iconUrl: string | null;
  iconEtag: string | null;
  updatedAt: string;
}

export interface SyncPayload {
  revision: number;
  serverTime: string;
  offlineValidUntil: string;
  snapshotDays: number;
  /** Background refresh cadence the server wants the client to use. */
  syncIntervalHours: number;
  announcement: Announcement | null;
  user: Pick<SessionUser, "name" | "department" | "mustChangePassword">;
  apps: AppTile[];
}

export interface ApiError {
  error: {
    code: string;
    message: string;
  };
}

export interface HealthResponse {
  status: "ok";
  version: string;
  appName: string;
}

// ---------------------------------------------------------------- admin portal

export interface AdminMe {
  user: SessionUser;
  isSuperAdmin: boolean;
}

export interface Stats {
  users: number;
  activeUsers: number;
  apps: number;
  enabledApps: number;
  groups: number;
  openResetRequests: number;
  loginsToday: number;
  revision: number;
}

export interface AdminApp {
  id: string;
  name: string;
  url: string;
  description: string | null;
  category: string | null;
  color: string | null;
  sortOrder: number;
  isEnabled: boolean;
  offlineVisible: boolean;
  iconSource: string;
  iconMime: string | null;
  iconFetchedAt: string | null;
  iconEtag: string | null;
  createdAt: string;
  updatedAt: string;
  deletedAt: string | null;
  departmentIds: string[];
  groupIds: string[];
  userIds: string[];
}

export interface Department {
  id: string;
  name: string;
  userCount: number;
  appCount: number;
  createdAt: string;
  updatedAt: string;
}

export interface AdminUser {
  id: string;
  email: string;
  name: string;
  department: string | null;
  role: Role;
  adminScope: { categories?: string[] } | null;
  isActive: boolean;
  mustChangePassword: boolean;
  lastLoginAt: string | null;
  createdAt: string;
  updatedAt: string;
  hasPassword: boolean;
}

export interface UserDetail extends AdminUser {
  groupIds: string[];
  appIds: string[];
}

export interface UserPage {
  users: AdminUser[];
  total: number;
}

export interface ImportErrorRow {
  line: number;
  email: string | null;
  message: string;
}

export interface ImportReport {
  created: number;
  updated: number;
  unchanged: number;
  errors: ImportErrorRow[];
}

export interface AuditRow {
  id: number;
  actorUserId: string | null;
  actorEmail: string | null;
  action: string;
  entityType: string;
  entityId: string | null;
  before: unknown;
  after: unknown;
  createdAt: string;
}

export interface AuditPage {
  entries: AuditRow[];
  total: number;
}

export interface Setting {
  key: string;
  value: unknown;
  updatedAt: string;
  updatedBy: string | null;
}
